package ai.eva.android.probe;
import android.app.*;import android.os.*;import android.webkit.*;import android.content.*;import android.net.Uri;import java.io.*;import java.nio.file.*;import org.json.*;
/** Bundled UI only. Remote web pages never receive this bridge. */
public class ShellActivity extends Activity {
 WebView web;boolean pageReady;
 static final Object saveLock=new Object();static final java.util.concurrent.atomic.AtomicLong saveRevision=new java.util.concurrent.atomic.AtomicLong();static final java.util.concurrent.ExecutorService storage=java.util.concurrent.Executors.newSingleThreadExecutor();

 void openRequestedPage(){if(!pageReady)return;String phoneThread=getIntent().getStringExtra("phone-thread");if(phoneThread!=null){getIntent().removeExtra("phone-thread");web.evaluateJavascript("window.openPhoneTask&&openPhoneTask("+JSONObject.quote(phoneThread)+")",null);return;}if("browser-check".equals(getIntent().getStringExtra("page"))){getIntent().removeExtra("page");startActivity(new Intent(this,BrowserActivity.class).putExtra("browser-check",true));return;}if("browser".equals(getIntent().getStringExtra("page"))){getIntent().removeExtra("page");startActivity(new Intent(this,BrowserActivity.class));return;}if("phone-report-preview".equals(getIntent().getStringExtra("page"))){getIntent().removeExtra("page");startActivity(new Intent(this,PhoneControlActivity.class).putExtra("report-preview",true));return;}if("phone-test".equals(getIntent().getStringExtra("page"))){getIntent().removeExtra("page");startActivity(new Intent(this,PhoneFixtureActivity.class));return;}if("phone-control".equals(getIntent().getStringExtra("page"))){getIntent().removeExtra("page");startActivity(new Intent(this,PhoneControlActivity.class));return;}String panel=getIntent().getStringExtra("panel");if(panel!=null){getIntent().removeExtra("panel");web.evaluateJavascript("models".equals(panel)?"openModelSheet()":"openAccountSheet()",null);}if("account".equals(getIntent().getStringExtra("page"))){getIntent().removeExtra("page");startActivity(new Intent(ShellActivity.this,AccountActivity.class));return;}if("settings".equals(getIntent().getStringExtra("page"))){getIntent().removeExtra("page");web.evaluateJavascript("settingsGo('settings')",null);}}
 protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);openRequestedPage();}
 public void onCreate(Bundle state){super.onCreate(state);web=new WebView(this);web.setBackgroundColor(-1);android.widget.FrameLayout frame=new android.widget.FrameLayout(this);frame.setBackgroundColor(-1);frame.addView(web,new android.widget.FrameLayout.LayoutParams(-1,-1));frame.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});setContentView(frame);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setDomStorageEnabled(false);web.addJavascriptInterface(new Bridge(),"EvaHost");web.setWebViewClient(new WebViewClient(){
 public void onPageFinished(WebView v,String url){pageReady=true;openRequestedPage();}
 public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}
 public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){String path=r.getUrl().getPath();if("https".equals(r.getUrl().getScheme())&&"eva.invalid".equals(r.getUrl().getHost())&&(path.equals("/index.html")||path.equals("/app.js")||path.equals("/settings.js")||path.equals("/pages.js")||path.equals("/models.js")||path.equals("/eva-stream-state.js")||path.equals("/eva-flow-view.js")||path.equals("/eva-markdown.js")||path.equals("/eva-account-quota.js")||path.equals("/model-panels.js")||path.equals("/workflows.js"))){try{return new WebResourceResponse(path.endsWith(".js")?"text/javascript":"text/html","UTF-8",getAssets().open(path.substring(1)));}catch(Exception ignored){}}return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}
 });web.loadUrl("https://eva.invalid/index.html");}
 protected void onActivityResult(int request,int result,Intent intent){super.onActivityResult(request,result,intent);if(request!=701)return;final String target=getSharedPreferences("eva-transfer",0).getString("target","");final String project=getSharedPreferences("eva-transfer",0).getString("project","");new Thread(()->{JSONObject response=new JSONObject();JSONArray files=new JSONArray();try{response.put("target",target);response.put("id",java.util.UUID.randomUUID().toString());if(result==RESULT_OK&&intent!=null){java.util.ArrayList<Uri> uris=new java.util.ArrayList<>();if(intent.getClipData()!=null){for(int n=0;n<intent.getClipData().getItemCount();n++)uris.add(intent.getClipData().getItemAt(n).getUri());}else if(intent.getData()!=null)uris.add(intent.getData());if(uris.size()>10)throw new IOException("每次最多选择 10 个附件");for(Uri uri:uris)files.put(WorkspaceFiles.importUri(this,uri,project));}response.put("files",files);}catch(Exception e){try{response.put("files",files).put("error",e instanceof SecurityException?"文件访问授权已失效，请重新选择":e.getMessage());}catch(Exception ignored){}}getSharedPreferences("eva-transfer",0).edit().putString("result",response.toString()).putBoolean("busy",false).commit();}).start();}
 class Bridge {
 @JavascriptInterface public String createProject(String id){try{WorkspaceFiles.project(ShellActivity.this,id);return "";}catch(Exception e){return e.getMessage();}}
 @JavascriptInterface public String attachmentResult(){return getSharedPreferences("eva-transfer",0).getString("result","{}");}
 @JavascriptInterface public void attachmentAck(){getSharedPreferences("eva-transfer",0).edit().remove("result").commit();}
 @JavascriptInterface public void pickAttachments(String target,String project,boolean photos){runOnUiThread(()->{if(getSharedPreferences("eva-transfer",0).getBoolean("busy",false))return;try{WorkspaceFiles.project(ShellActivity.this,project);getSharedPreferences("eva-transfer",0).edit().putString("target",target).putString("project",project).putBoolean("busy",true).commit();try{startActivityForResult(WorkspaceFiles.picker(ShellActivity.this,photos),701);}catch(ActivityNotFoundException unavailable){Intent fallback=new Intent(Intent.ACTION_GET_CONTENT).addCategory(Intent.CATEGORY_OPENABLE).setType(photos?"image/*":"*/*").putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(fallback,701);}}catch(Exception e){getSharedPreferences("eva-transfer",0).edit().putBoolean("busy",false).commit();android.widget.Toast.makeText(ShellActivity.this,"无法打开文件选择器",1).show();}});}

 @JavascriptInterface public boolean providerChoice(String id){try{new ModelStore(ShellActivity.this).select(id);return true;}catch(Exception e){return false;}}
 @JavascriptInterface public boolean accountChoice(String model,String effort,String tier){if(model.length()>200||effort.length()>30||tier.length()>80)return false;return getSharedPreferences("eva-account",0).edit().putString("model",model).putString("effort",effort).putString("serviceTier",tier).putBoolean("preferred",true).commit();}
 @JavascriptInterface public String providers(){try{return new ModelStore(ShellActivity.this).publicConfig().toString();}catch(Exception e){return "{\"providers\":[],\"active\":\"\",\"error\":\"配置读取失败\"}";}}
 @JavascriptInterface public void kernelCall(String ticket,String method,String params){KernelHost.get(ShellActivity.this).call(ticket,method,params);}
 @JavascriptInterface public String kernelDrain(){return KernelHost.get(ShellActivity.this).drain();}
 @JavascriptInterface public void kernelRespond(String id,String result){KernelHost.get(ShellActivity.this).respond(id,result);}
 @JavascriptInterface public String modelStart(String id,String provider,String model,String input){return "{\"state\":\"failed\",\"error\":\"Direct transport retired; use Codex app-server\"}";}
 @JavascriptInterface public String modelPoll(String id){return ModelClient.poll(ShellActivity.this,id);}
 @JavascriptInterface public void modelCancel(String id){ModelClient.cancel(id);}
 @JavascriptInterface public void modelAck(String id){getSharedPreferences("eva-model-jobs",0).edit().remove(id).commit();}

 @JavascriptInterface public String settings(){try{android.content.SharedPreferences p=getSharedPreferences("eva-settings",0);JSONObject o=new JSONObject();o.put("commandTimeout",p.getInt("commandTimeout",120));o.put("browserHome",p.getString("browserHome","https://example.com"));o.put("browserDesktop",p.getBoolean("browserDesktop",true));o.put("theme",p.getString("theme","light"));o.put("freeMiB",getFilesDir().getUsableSpace()/1024/1024);o.put("rootfs",new File(getFilesDir(),"alpine/bin/busybox").isFile());return o.toString();}catch(Exception e){return "{}";}}
 @JavascriptInterface public String setSetting(String key,String value){try{android.content.SharedPreferences.Editor e=getSharedPreferences("eva-settings",0).edit();if(key.equals("commandTimeout")){int n=Integer.parseInt(value);if(n!=30&&n!=60&&n!=120&&n!=300)throw new IllegalArgumentException("不支持的超时值");e.putInt(key,n);}else if(key.equals("browserHome")){if(value.length()>2048)throw new IllegalArgumentException("地址过长");e.putString(key,SettingsActivity.validateUrl(value));}else if(key.equals("browserDesktop")){if(!value.equals("true")&&!value.equals("false"))throw new IllegalArgumentException("无效浏览模式");e.putBoolean(key,Boolean.parseBoolean(value));}else if(key.equals("theme")){if(!value.equals("light")&&!value.equals("dark"))throw new IllegalArgumentException("不支持的主题");e.putString(key,value);}else throw new IllegalArgumentException("不支持的设置");if(!e.commit())throw new IOException("保存失败");return settings();}catch(Exception e){try{return new JSONObject().put("error",e.getMessage()).toString();}catch(Exception ignored){return "{}";}}}
 @JavascriptInterface public String load(){return getSharedPreferences("eva-ui",0).getString("state","{\"chats\":[],\"draft\":\"\",\"active\":null}");}
 @JavascriptInterface public boolean save(String value){long revision=saveRevision.incrementAndGet();synchronized(saveLock){return saveValue(value,revision);}}
 boolean saveValue(String value,long revision){try{if(revision!=saveRevision.get())return true;if(value.length()>2000000)return false;new JSONObject(value);return getSharedPreferences("eva-ui",0).edit().putString("state",value).commit();}catch(Exception ignored){return false;}}
 @JavascriptInterface public void saveLater(String value){long revision=saveRevision.incrementAndGet();storage.execute(()->{boolean ok;synchronized(saveLock){ok=saveValue(value,revision);}if(!ok)try{KernelHost.get(ShellActivity.this).emit(new JSONObject().put("method","android/storageError"));}catch(Exception ignored){}});}
 @JavascriptInterface public String tasks(){JSONArray result=new JSONArray();File[] list=new File(getFilesDir(),"alpine/root/eva-tasks").listFiles();if(list!=null){java.util.Arrays.sort(list,(a,b)->Long.compare(b.lastModified(),a.lastModified()));for(File f:list){try{JSONObject t=new JSONObject(new String(Files.readAllBytes(new File(f,"state.json").toPath()),"UTF-8"));JSONObject item=new JSONObject();item.put("id",f.getName());item.put("state",t.optString("state"));item.put("command",t.getJSONArray("argv").optString(2));result.put(item);}catch(Exception ignored){}}}return result.toString();}
 @JavascriptInterface public String taskDetail(String id){try{
 if(!id.matches("[a-zA-Z0-9-]{1,64}"))throw new IOException("无效任务编号");
 File folder=new File(getFilesDir(),"alpine/root/eva-tasks/"+id),file=new File(folder,"state.json");
 JSONObject t=new JSONObject(new String(Files.readAllBytes(file.toPath()),"UTF-8"));
 t.put("id",id);t.put("command",t.getJSONArray("argv").optString(2));t.put("updated",file.lastModified());t.put("errorMessage",t.optString("error"));t.remove("error");
 ByteArrayOutputStream out=new ByteArrayOutputStream(),err=new ByteArrayOutputStream();boolean truncated=t.optBoolean("outputTruncated");
 File events=new File(folder,"events.jsonl");if(events.isFile())try(BufferedReader reader=new BufferedReader(new InputStreamReader(new FileInputStream(events),"UTF-8"))){String line;while((line=reader.readLine())!=null){try{JSONObject e=new JSONObject(line);if(e.optString("type").equals("output")){ByteArrayOutputStream dest=e.optString("stream").equals("stderr")?err:out;byte[] bytes=android.util.Base64.decode(e.getString("base64"),android.util.Base64.DEFAULT);int remain=131072-dest.size();dest.write(bytes,0,Math.min(remain,bytes.length));if(bytes.length>remain)truncated=true;}}catch(JSONException ignored){}}}
 t.put("stdout",out.toString("UTF-8"));t.put("stderr",err.toString("UTF-8"));t.put("truncated",truncated);return t.toString();
 }catch(Exception e){try{return new JSONObject().put("error",e.getMessage()).toString();}catch(Exception ignored){return "{}";}}}
 @JavascriptInterface public void open(String kind){runOnUiThread(()->{if(kind.equals("phone-control")){startActivity(new Intent(ShellActivity.this,PhoneControlActivity.class));return;}if(kind.equals("account")){startActivity(new Intent(ShellActivity.this,AccountActivity.class));return;}if(kind.equals("models")){startActivity(new Intent(ShellActivity.this,ModelsActivity.class));return;}if(kind.equals("settings")){web.evaluateJavascript("settingsGo('settings')",null);return;}if(kind.equals("app-settings")){startActivity(new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName())));return;}if(kind.equals("diagnostics")){startActivity(new Intent(ShellActivity.this,MainActivity.class));return;}if(kind.equals("tools")){new AlertDialog.Builder(ShellActivity.this).setTitle("此手机工具").setItems(new String[]{"本地终端","工作区","Eva 浏览器"},(d,n)->open(new String[]{"terminal","files","browser"}[n])).show();return;}if(kind.equals("terminal")||kind.equals("files")||kind.equals("browser")){Intent intent=new Intent(ShellActivity.this,kind.equals("terminal")?TerminalActivity.class:kind.equals("files")?FilesActivity.class:BrowserActivity.class);startActivity(intent);}});}
 }
 protected void onResume(){super.onResume();PhoneTaskService.restore(this);if(web!=null)web.evaluateJavascript("window.kernelPollingEnabled=true;window.modelRefresh&&modelRefresh()",null);}
 protected void onPause(){if(web!=null)web.evaluateJavascript("window.kernelPollingEnabled=false",null);new Handler().postDelayed(()->{if(!isDestroyed()&&BrowserActivity.live!=null&&web!=null)web.evaluateJavascript("window.kernelPollingEnabled=true",null);},500);super.onPause();}
 public void onBackPressed(){web.evaluateJavascript("window.evaBack?evaBack():false",result->{if(!"true".equals(result))finish();});}
 protected void onDestroy(){web.removeJavascriptInterface("EvaHost");web.destroy();super.onDestroy();}
}
